// math/log_f64_table.c
//
// The data that rc_log_f64 and rc_pow_f64 share: their constants, and the log table. For each of
// 256 intervals of the significand m in [1, 2), the table holds the c = j / 512 nearest 1 / m
// across it, and -log(c). The first interval takes c = 1 and the last c = 1/2, so that around
// x = 1 the table adds nothing, and r = m c - 1 stays in [-2^-8.45, 2^-8) everywhere. Generated by
// tools/math/exp_log_f64/gen_tables.py, which chooses each j with exact rationals and rounds
// -log(c), worked out by mpmath at 300 bits, to a multiple of 2^-42 and the nearest double to what
// is left. 4.5 KiB.

#include "math/exp_log_f64.h"

// log1p(r) = r - r^2 / 2 + r^3 (L3 + L4 r + L5 r^2 + L6 r^3 + L7 r^4) within 2^-65.9 |r| for r in
// [-2^-8.45, 2^-8], by tools/math/exp_log_f64/fit_exp_log_f64.sollya.
const rc_log_f64_constants rc_log_f64_data = {
    .k_bias = 0x1p52 + 1023.0,
    .r_scale = 0x1p-61,
    .ln2_hi = 0x1.62e42fefa3800p-1,
    .ln2_lo = 0x1.ef35793c76730p-45,
    .minus_half = -0.5,
    .poly = {0x1.5555555555478p-2, -0x1.ffffffffd5cc1p-3, 0x1.99999a4a4591bp-3, -0x1.5556254200038p-3, 0x1.23a5f0d3415ap-3}
};


// log1p(r) = r - r^2 / 2 + r^3 (P3 + P4 r + P5 r^2 + P6 r^3 + P7 r^4 + P8 r^5) within 2^-74 |r|
